    enonce: "<span class=\"q\">1) </span>أجب بصواب أو خطأ مع التعليل: باقي القسمة الإقليدية لـ 1905 على 7 هو 6<br><span class=\"q\">2) </span>أجب بصواب أو خطأ مع التعليل: عدد صحيح زوجي و عدد صحيح فردي يكونان دائما أوليين فيما بينهما<br><span class=\"q\">3) </span>أجب بصواب أو خطأ مع التعليل: مهما يكن العدد الصحيح n فإنّ <span dir=\"ltr\" class=\"expr\">16n + 24</span> يقبل القسمة على 8<br><span class=\"q\">4) </span>أجب بصواب أو خطأ مع التعليل: إذا كان <span dir=\"ltr\" class=\"expr\">x = 12y + 6</span> فإنّ باقي قسمة x على 4 هو 6",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نبحث عن الخارج","math":"أكبر مضاعف لـ 7 لا يفوق 1905 هو <span dir=\"ltr\" class=\"expr\">7 × 272</span>"},{"quoi":"نحسب هذا المضاعف","math":"<span dir=\"ltr\" class=\"expr\">7 × 272 = 1904</span>"},{"quoi":"نحسب الباقي","math":"<span dir=\"ltr\" class=\"expr\">1905 - 1904 = 1</span>"},{"quoi":"نتحقّق من الشرط","math":"<span dir=\"ltr\" class=\"expr\">1 &lt; 7</span>"},{"quoi":"نكتب القسمة الإقليدية","math":"<span dir=\"ltr\" class=\"expr\">1905 = 7 × 272 + 1</span>"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ما تقوله العبارة","math":"العبارة تدّعي أنّ الزوجية و الفردية تكفيان للأوّلية فيما بينهما"},{"quoi":"نبحث عن مثال مضادّ","math":"نأخذ 6 و هو زوجي، و 9 و هو فردي"},{"quoi":"نفكّك العددين","math":"<span dir=\"ltr\" class=\"expr\">6 = 3 × 2</span> و <span dir=\"ltr\" class=\"expr\">9 = 3 × 3</span>"},{"quoi":"نحسب القاسم المشترك","math":"العدد 3 يقسم 6 و يقسم 9"},{"quoi":"نستنتج","math":"ق.م.أ لهما يقبل القسمة على 3 فهو ليس 1"},{"quoi":"الجواب","math":"خطأ"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نقسم المعامل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">16 = 8 × 2</span>"},{"quoi":"نقسم الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">24 = 8 × 3</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">16n + 24 = 8(2n + 3)</span>"},{"quoi":"نستنتج","math":"العبارة مكتوبة <span dir=\"ltr\" class=\"expr\">8 ×</span> عدد صحيح، مهما يكن n"},{"quoi":"الجواب","math":"صواب"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"شرط الباقي","math":"الباقي في القسمة على 4 يجب أن يكون أصغر تماما من 4"},{"quoi":"نقارن","math":"<span dir=\"ltr\" class=\"expr\">6 &gt; 4</span>"},{"quoi":"العدد المقترح ليس باقيا","math":"العدد 6 لا يمكن أن يكون باقي قسمة على 4"},{"quoi":"نُظهر الباقي الحقيقي","math":"<span dir=\"ltr\" class=\"expr\">6 = 4 × 1 + 2</span>"},{"quoi":"نعيد كتابة x","math":"<span dir=\"ltr\" class=\"expr\">12y + 6 = 4(3y + 1) + 2</span>"},{"quoi":"الباقي الحقيقي","math":"الباقي هو 2 لأنّ 2 < 4"},{"quoi":"الجواب","math":"خطأ"}],
