    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">8<sup>647</sup> = 2<sup>1941</sup></span>"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">4<sup>969</sup> = 2<sup>1938</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1941</sup> + n × 2<sup>1938</sup> = 2<sup>1938</sup>(2<sup>3</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">44 = 4 × 11</span>"},{"quoi":"العامل 4 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1938</sup> = 2<sup>2</sup> × 2<sup>1936</sup></span>"},{"quoi":"يبقى الشرط على 11","math":"بما أنّ 11 و 2 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">2<sup>3</sup> + n</span> القسمة على 11"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">2<sup>3</sup> = 8</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 30 بحيث يقبل <span dir=\"ltr\" class=\"expr\">8 + n</span> القسمة على 11"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 3 ؛ 14 ؛ 25</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">16<sup>199</sup> = 2<sup>796</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>796</sup> + n × 2<sup>795</sup> = 2<sup>795</sup>(2 + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">28 = 4 × 7</span>"},{"quoi":"العامل 4 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">2<sup>795</sup> = 2<sup>2</sup> × 2<sup>793</sup></span>"},{"quoi":"يبقى الشرط على 7","math":"بما أنّ 7 و 2 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">2 + n</span> القسمة على 7"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">2 = 2</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 30 بحيث يقبل <span dir=\"ltr\" class=\"expr\">2 + n</span> القسمة على 7"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 5 ؛ 12 ؛ 19 ؛ 26</span>"}],
